151	func TestSplitRejectedIsAtomic(t *testing.T) {
152		s, _ := fixedStore(t)
153		mustRegister(t, s, "P", "5.000", "h", "l")
154		mustRegister(t, s, "EXIST", "1", "h", "l")
155	
156		before, _ := s.GetSample("P")
157	
158		// 超量：整次分装不生效。
159		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
160			{ID: "A", Qty: "3.000"},
161			{ID: "B", Qty: "2.001"}, // 合计 5.001 > 5.000
162		}}); !errors.Is(err, ErrConflict) {
163			t.Fatalf("超量分装应返回 ErrConflict, got %v", err)
164		}
165	
166		// 批次内编号重复。
167		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
168			{ID: "A", Qty: "1"},
169			{ID: "A", Qty: "1"},
