171			t.Fatalf("批内重复编号应拒绝, got %v", err)
172		}
173	
174		// 编号与既有样品冲突。
175		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
176			{ID: "EXIST", Qty: "1"},
177		}}); !errors.Is(err, ErrConflict) {
