182		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
183			{ID: "A", Qty: "1.0001"},
184		}}); !errors.Is(err, ErrInvalid) {
185			t.Fatalf("非法数量应拒绝, got %v", err)
186		}
187	
188		// 空批次与不存在的来源。
189		if _, err := s.Split(SplitInput{ParentID: "P"}); !errors.Is(err, ErrInvalid) {
190			t.Fatalf("空批次应拒绝, got %v", err)
191		}
192		if _, err := s.Split(SplitInput{ParentID: "NOPE", Parts: []SplitPart{{ID: "A", Qty: "1"}}}); !errors.Is(err, ErrNotFound) {
193			t.Fatalf("不存在来源应 ErrNotFound, got %v", err)
