func (l *ledger) deepCopy() *ledger {
	cp := newLedger()
	for id, s := range l.Samples {
		sc := *s
		sc.Children = append([]string(nil), s.Children...)
		sc.History = make([]historyRecord, len(s.History))
		copy(sc.History, s.History)
		cp.Samples[id] = &sc
	}
